let audioEngineInstance: AudioEngine | null = null
export function getAudioEngine(config?: Partial<AudioEngineConfig>): AudioEngine { audioEngineInstance ??= new AudioEngine(config); return audioEngineInstance }

export interface ClipAudioResolutionTimeline { tracks?: Array<Record<string, unknown>> }
export function findClipTrack(timeline: ClipAudioResolutionTimeline, clipId: string): { clip: Record<string, unknown>; track: Record<string, unknown> } | null { for (const track of timeline.tracks ?? []) { const clips = Array.isArray(track.clips) ? track.clips as Array<Record<string, unknown>> : []; const clip = clips.find(candidate => candidate.id === clipId); if (clip) return { clip, track } } return null }
export function getLinkedAudioClips(clip: Record<string, unknown>, timeline: ClipAudioResolutionTimeline): Array<{ clip: Record<string, unknown>; track: Record<string, unknown> }> { const clipId = String(clip.id ?? ''); const mediaId = String(clip.mediaId ?? ''); const start = finite(clip.startTime); const sourceTime = finite(clip.inPoint); return (timeline.tracks ?? []).flatMap(track => (Array.isArray(track.clips) ? track.clips as Array<Record<string, unknown>> : []).filter(candidate => String(candidate.id ?? '') !== clipId && String(candidate.mediaId ?? '') === mediaId && Math.abs(finite(candidate.startTime) - start) < 0.01 && Math.abs(finite(candidate.inPoint) - sourceTime) < 0.01).map(candidate => ({ clip: candidate, track }))) }
export function resolveClipAudioEffects(clip: Record<string, unknown>, timeline: ClipAudioResolutionTimeline): Effect[] { const direct = Array.isArray(clip.effects) ? clip.effects as Effect[] : []; return direct.length ? direct : getLinkedAudioClips(clip, timeline).flatMap(item => Array.isArray(item.clip.effects) ? item.clip.effects as Effect[] : []) }
export function resolveClipVolumeAutomation(clip: Record<string, unknown>, timeline: ClipAudioResolutionTimeline): AutomationPoint[] { const automation = clip.automation as Record<string, unknown> | undefined; const direct = Array.isArray(automation?.volume) ? automation.volume as AutomationPoint[] : []; return direct.length ? direct : getLinkedAudioClips(clip, timeline).flatMap(item => { const linked = item.clip.automation as Record<string, unknown> | undefined; return Array.isArray(linked?.volume) ? linked.volume as AutomationPoint[] : [] }) }
export function resolveAudibleAudioTarget(clip: Record<string, unknown>, timeline: ClipAudioResolutionTimeline): Record<string, unknown> { return getLinkedAudioClips(clip, timeline).find(item => item.track.type === 'audio')?.clip ?? clip }
export function getTrackTransitionAudioFades(track: { transitions?: Array<Record<string, unknown>> }, clipId: string): { fadeIn: number; fadeOut: number } { let fadeIn = 0; let fadeOut = 0; for (const transition of track.transitions ?? []) { if ((transition.params as Record<string, unknown> | undefined)?.audioFade !== true) continue; const duration = Math.max(0, finite(transition.duration)); const clipA = String(transition.clipAId ?? ''); const clipB = String(transition.clipBId ?? ''); if (clipB) { if (clipA === clipId) fadeOut = Math.max(fadeOut, duration / 2); if (clipB === clipId) fadeIn = Math.max(fadeIn, duration / 2) } else if (clipA === clipId) { if (transition.edge === 'in') fadeIn = Math.max(fadeIn, duration); else fadeOut = Math.max(fadeOut, duration) } } return { fadeIn, fadeOut } }

export interface AudioFileProcessOptions { input: string; outputDir: string; outputName?: string; effects?: Effect[]; volume?: number; pan?: number; automation?: VolumeKeyframe[]; fadeIn?: number; fadeOut?: number }
export async function processAudioFile(options: AudioFileProcessOptions): Promise<{ path: string; buffer: PCMBuffer; effects: string[] }> { let buffer = await readAudio(options.input, options.outputDir); buffer = applyVolumeAutomation(buffer, options.automation, options.volume ?? 1); buffer = applyFades(buffer, options.fadeIn ?? 0, options.fadeOut ?? 0); buffer = applyPan(buffer, options.pan ?? 0); const result = applyEffects(buffer, options.effects ?? []); const directory = await ensureOutputDir(options.outputDir); const path = join(directory, options.outputName ?? `${slugify(options.input, 36)}-processed-${Date.now().toString(36)}.wav`); await writeWavFile(path, result.buffer); return { path, buffer: result.buffer, effects: result.appliedEffects } }
export async function ffmpegAudioProcess(input: string, output: string, filters: string[]): Promise<string> { const result = spawnSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', '-i', input, '-af', filters.join(','), output], { encoding: 'utf8' }); if (result.status !== 0) throw new Error(`ffmpeg audio filter failed: ${result.stderr?.trim() || `exit ${result.status}`}`); return output }
